css:
/* Проявление заголовка первого экрана построчно через маску.
   Только CSS: стартует с первого кадра, без ожидания JS. */
:root {
  --htr-dur: 800ms;                       /* строка заголовка */
  --htr-step: 90ms;                       /* шаг между строками */
  --htr-ease: cubic-bezier(.05, .7, .1, 1); /* вход: MD3 Emphasized */
  --htr-follow: 380ms;                    /* старт подзаголовка */
}
@media (max-width: 640px) {
  :root { --htr-dur: 640ms; --htr-step: 60ms; --htr-follow: 300ms; }
}

/* grid: отрицательные отступы строк не схлопываются,
   раскладка совпадает с обычным заголовком */
.htr { display: grid; margin: 0; }

/* Маска строки. Запас .15em по вертикали — чтобы не срезать
   Й, Ё сверху и Д, Ц, Щ, у снизу при line-height около 1;
   отрицательный margin возвращает раскладку на место. */
.htr-line {
  display: block;
  overflow: hidden;
  overflow: clip;
  padding: .15em .08em;
  margin: -.15em -.08em;
}
.htr-in { display: block; text-wrap: balance; }

@media (prefers-reduced-motion: no-preference) {
  .htr-in { animation: htr-rise var(--htr-dur) var(--htr-ease) backwards; }
  .htr-line:nth-child(2) .htr-in { animation-delay: var(--htr-step); }
  .htr-line:nth-child(3) .htr-in { animation-delay: calc(var(--htr-step) * 2); }
  .htr-line:nth-child(4) .htr-in { animation-delay: calc(var(--htr-step) * 3); }
  .htr-sub { animation: htr-fade-up 560ms cubic-bezier(.2, 0, 0, 1) var(--htr-follow) backwards; }
  .htr-cta { animation: htr-fade-up 520ms cubic-bezier(.2, 0, 0, 1) calc(var(--htr-follow) + 100ms) backwards; }
}

/* Уменьшение движения: строки стоят на месте сразу,
   подзаголовок и кнопка только коротко проявляются, без сдвига */
@media (prefers-reduced-motion: reduce) {
  .htr-in { animation: none; }
  .htr-sub, .htr-cta { animation: htr-fade 180ms ease-out backwards; }
}

/* Сдвиг на высоту строки плюс запас маски: строка целиком под краем */
@keyframes htr-rise {
  from { transform: translateY(calc(100% + .35em)); }
}
@keyframes htr-fade-up {
  from { opacity: 0; transform: translateY(12px); }
}
@keyframes htr-fade {
  from { opacity: 0; }
}
